//! SendGrid dispatch with tracking across synchronous PostgreSQL promotion.
use novu_postgres_queue::{self as queue, sendgrid::{Config,Region,Sendgrid},sendgrid_queue};
use serde_json::{Value,json};
use std::{process::{Child,Command,Stdio},sync::{Arc,atomic::{AtomicUsize,Ordering}},time::Duration};
use tokio::{io::{AsyncReadExt,AsyncWriteExt},net::TcpListener};
use tokio_postgres::{Client,NoTls};
use uuid::Uuid;
async fn connect(url:&str)->Client {for _ in 0..100 {if let Ok((db,driver))=tokio_postgres::connect(url,NoTls).await {tokio::spawn(driver);return db;}tokio::time::sleep(Duration::from_millis(100)).await;}panic!("database unavailable")}
struct Worker(Child);
impl Drop for Worker {fn drop(&mut self){let _=self.0.kill();let _=self.0.wait();}}
fn worker(url:&str,name:&str,proxy:&str)->Worker {Worker(Command::new(env!("CARGO_BIN_EXE_sendgrid-worker")).env_clear().env("DATABASE_URL",format!("{url}&application_name={name}")).env("NOVU_POSTGRES_ALLOW_INSECURE","true").env("NOVU_SENDGRID_ENVIRONMENT_ID","sendgrid-inflight-ha").env("NOVU_SENDGRID_API_KEY","fixture").env("NOVU_SENDGRID_FROM","sender@example.test").env("NOVU_SENDGRID_SENDER_NAME","Sender").env("NOVU_SENDGRID_DISPATCH_TRACKING","true").env("HTTPS_PROXY",proxy).env("https_proxy",proxy).env("HTTP_PROXY",proxy).env("http_proxy",proxy).env("ALL_PROXY",proxy).env("all_proxy",proxy).env("NO_PROXY","").env("no_proxy","").stdout(Stdio::null()).stderr(Stdio::null()).spawn().unwrap())}
#[tokio::test]
#[ignore = "requires disposable synchronous local PostgreSQL pair; stops primary"]
async fn inflight_sendgrid_tracking_remains_unknown_without_automatic_resend() {
 let primary_url=std::env::var("TEST_PRIMARY_URL").unwrap();let standby_url=std::env::var("TEST_STANDBY_URL").unwrap();let cluster_url=std::env::var("TEST_FAILOVER_URL").unwrap();let primary=std::env::var("TEST_LOCAL_PRIMARY_DATA").unwrap();let standby=std::env::var("TEST_LOCAL_STANDBY_DATA").unwrap();let pgctl=std::env::var("TEST_LOCAL_PG_CTL").unwrap();
 let mut db=connect(&primary_url).await;db.batch_execute("INSERT INTO public.novu_rust_environments VALUES('sendgrid-inflight-ha','org')").await.unwrap();
 let job=Uuid::new_v4();queue::enqueue(&db,job,"sendgrid-inflight-ha",sendgrid_queue::JOB_KIND,&json!({"to":["recipient@example.test"],"subject":"Hello","html":"<p>Hi</p>","tracking_settings":{"clickTracking":{"enable":true,"enableText":false},"subscriptionTracking":{"enable":true,"text":"fixture"}}})).await.unwrap();
 let listener=TcpListener::bind("127.0.0.1:0").await.unwrap();let endpoint=format!("http://{}/send",listener.local_addr().unwrap());let (received_tx,received_rx)=tokio::sync::oneshot::channel();let (release_tx,release_rx)=tokio::sync::oneshot::channel();
 let server=tokio::spawn(async move{let(mut stream,_)=listener.accept().await.unwrap();let mut bytes=Vec::new();let mut chunk=[0u8;4096];loop {let n=stream.read(&mut chunk).await.unwrap();assert!(n>0);bytes.extend_from_slice(&chunk[..n]);if let Some(pos)=bytes.windows(4).position(|v|v==b"\r\n\r\n"){let headers=String::from_utf8_lossy(&bytes[..pos]);let size=headers.lines().find_map(|v|v.to_ascii_lowercase().strip_prefix("content-length: ").and_then(|s|s.parse::<usize>().ok())).unwrap();if bytes.len()>=pos+4+size {let value:Value=serde_json::from_slice(&bytes[pos+4..pos+4+size]).unwrap();received_tx.send(value).unwrap();break;}}}release_rx.await.unwrap();let _=stream.write_all(b"HTTP/1.1 202 Accepted\r\nContent-Length: 0\r\nConnection: close\r\n\r\n").await;});
 let processor=tokio::spawn(async move{let provider=Sendgrid::test_endpoint(Config{api_key:"fixture".into(),from:"sender@example.test".into(),sender_name:"Sender".into(),region:Region::Global},&endpoint).unwrap().with_dispatch_tracking();sendgrid_queue::process_one(&mut db,"sendgrid-inflight-ha",&provider).await});
 let body=tokio::time::timeout(Duration::from_secs(10),received_rx).await.unwrap().unwrap();assert_eq!(body["tracking_settings"],json!({"click_tracking":{"enable":true,"enable_text":false},"subscription_tracking":{"enable":true,"text":"fixture"}}));
 let replica=connect(&standby_url).await;let mut replicated=false;for _ in 0..100 {replicated=replica.query_opt("SELECT 1 FROM public.novu_queue_jobs j JOIN public.novu_rust_sendgrid_attempts a ON a.job_id=j.id JOIN public.novu_rust_sendgrid_dispatch_ids d ON d.id=a.dispatch_id WHERE j.id=$1 AND j.status='running' AND a.state='dispatching'",&[&job]).await.unwrap().is_some();if replicated{break;}tokio::time::sleep(Duration::from_millis(50)).await;}assert!(replicated);
 assert!(Command::new(&pgctl).args(["-D",&primary,"-m","immediate","stop","-w"]).stdout(Stdio::null()).status().unwrap().success());assert!(Command::new(&pgctl).args(["-D",&standby,"promote","-w"]).stdout(Stdio::null()).status().unwrap().success());
 release_tx.send(()).unwrap();server.await.unwrap();assert!(processor.await.unwrap().is_err());
 let promoted=connect(&standby_url).await;promoted.execute("UPDATE public.novu_queue_jobs SET lease_until=clock_timestamp()-interval '1 second' WHERE id=$1",&[&job]).await.unwrap();
 let proxy_listener=TcpListener::bind("127.0.0.1:0").await.unwrap();let proxy=format!("http://{}",proxy_listener.local_addr().unwrap());let count=Arc::new(AtomicUsize::new(0));let seen=count.clone();let proxy_task=tokio::spawn(async move{while let Ok((socket,_))=proxy_listener.accept().await{seen.fetch_add(1,Ordering::SeqCst);drop(socket);}});
 let mut first=worker(&cluster_url,"sendgrid_ha_1",&proxy);let mut second=worker(&cluster_url,"sendgrid_ha_2",&proxy);let mut recovered=false;
 for _ in 0..200 {recovered=promoted.query_opt("SELECT 1 FROM public.novu_queue_jobs j JOIN public.novu_rust_sendgrid_attempts a ON a.job_id=j.id WHERE j.id=$1 AND j.status='failed' AND a.state='unknown'",&[&job]).await.unwrap().is_some();if recovered{break;}assert!(first.0.try_wait().unwrap().is_none()&&second.0.try_wait().unwrap().is_none());tokio::time::sleep(Duration::from_millis(100)).await;}assert!(recovered);
 let mut connected=false;for _ in 0..200 {connected=promoted.query_one("SELECT count(*) FROM pg_stat_activity WHERE application_name IN ('sendgrid_ha_1','sendgrid_ha_2')",&[]).await.unwrap().get::<_,i64>(0)==2;if connected{break;}tokio::time::sleep(Duration::from_millis(100)).await;}assert!(connected);tokio::time::sleep(Duration::from_secs(2)).await;assert_eq!(count.load(Ordering::SeqCst),0);
 let next=Uuid::new_v4();queue::enqueue(&promoted,next,"sendgrid-inflight-ha",sendgrid_queue::JOB_KIND,&json!({"to":["recipient@example.test"],"subject":"Next","html":"<p>next</p>"})).await.unwrap();let mut processed=false;for _ in 0..200 {processed=promoted.query_opt("SELECT 1 FROM public.novu_queue_jobs j JOIN public.novu_rust_sendgrid_attempts a ON a.job_id=j.id WHERE j.id=$1 AND j.status='failed' AND a.state='unknown'",&[&next]).await.unwrap().is_some();if processed{break;}tokio::time::sleep(Duration::from_millis(100)).await;}assert!(processed);tokio::time::sleep(Duration::from_secs(2)).await;assert_eq!(count.load(Ordering::SeqCst),1);proxy_task.abort();
}
